// ==UserScript==
// @name         Capture Flow
// @namespace    https://github.com/xiaoqianran/capture-flow
// @version      0.2.0
// @description  实时采集当前页面 DOM 到 Local Hub，并通过持久化 AI 队列按固定并发后台处理
// @author       capture-flow
// @match        *://*/*
// @connect      127.0.0.1
// @connect      localhost
// @connect      *
// @grant        GM_xmlhttpRequest
// @grant        GM_addStyle
// @grant        GM_setValue
// @grant        GM_getValue
// @run-at       document-idle
// @license      MIT
// ==/UserScript==

(() => {
  "use strict";
  const K = { hub: "cf.hubUrl", autoAi: "cf.autoAi", autoCapture: "cf.autoCapture", recipe: "cf.recipeId", open: "cf.panelOpen" };
  const DEFAULT_HUB = "http://127.0.0.1:8080";
  const $ = (s) => document.querySelector(s);
  const get = (k, d) => Promise.resolve(GM_getValue(k, d));
  const set = (k, v) => Promise.resolve(GM_setValue(k, v));
  async function settings() { return { hub: String(await get(K.hub, DEFAULT_HUB)).replace(/\/$/, ""), autoAi: Boolean(await get(K.autoAi, false)), autoCapture: Boolean(await get(K.autoCapture, false)), recipe: String(await get(K.recipe, "summarize")), open: Boolean(await get(K.open, true)) }; }
  function request(path, init = {}) { return settings().then((cfg) => new Promise((resolve, reject) => { GM_xmlhttpRequest({ method: init.method || "GET", url: cfg.hub + path, headers: { "Content-Type": "application/json" }, data: init.body, timeout: 15000, onload: (r) => { let data; try { data = r.responseText ? JSON.parse(r.responseText) : null; } catch { reject(new Error(`invalid JSON: ${r.responseText.slice(0,160)}`)); return; } if (r.status < 200 || r.status >= 300) { reject(new Error(data?.error_message || data?.error_code || `HTTP ${r.status}`)); return; } resolve(data); }, onerror: () => reject(new Error("Local Hub unreachable")), ontimeout: () => reject(new Error("Local Hub timeout")) }); })); }
  const DROP = "script,style,noscript,svg,canvas,iframe,nav,footer,aside,form,button,input,textarea,select,#cf-root,[aria-hidden='true']";
  const ROOTS = ["article","main","[role='main']",".Post-RichTextContainer",".RichContent-inner",".article-content",".post-content",".entry-content","body"];
  const clean = (s) => String(s || "").replace(/\r/g,"").replace(/[ \t]+\n/g,"\n").replace(/\n[ \t]+/g,"\n").replace(/\n{3,}/g,"\n\n").replace(/[ \t]{2,}/g," ").trim();
  function contentRoot(){ let best=document.body||document.documentElement,bestLen=-1; for(const selector of ROOTS){ for(const el of document.querySelectorAll(selector)){ const n=clean(el.textContent).length; if(n>bestLen){best=el;bestLen=n;} } if(bestLen>1200&&selector!=="body") break; } return best; }
  function meta(...selectors){ for(const s of selectors){ const v=document.querySelector(s)?.content?.trim(); if(v) return v; } return ""; }
  function snapshot(){ const root=contentRoot(), clone=root.cloneNode(true); clone.querySelectorAll(DROP).forEach(n=>n.remove()); clone.querySelectorAll("h1,h2,h3,h4,h5,h6,p,li,pre,blockquote,br,section,div").forEach(n=>{if(n.tagName==="BR")n.replaceWith("\n");else n.append("\n");}); const text=clean(clone.textContent||document.body?.innerText||""); if(!text) throw new Error("页面正文为空"); const title=meta("meta[property='og:title']","meta[name='twitter:title']")||$("h1")?.textContent?.trim()||document.title?.trim()||location.href; const author=meta("meta[name='author']","meta[property='article:author']","meta[name='byl']")||$("[rel='author']")?.textContent?.trim()||""; const canonical=$("link[rel='canonical']")?.href?.trim(); const url=canonical&&/^https?:\/\//i.test(canonical)?canonical:location.href; const raw=root.cloneNode(true); raw.querySelectorAll(DROP).forEach(n=>n.remove()); return {url,title,author,content_md:(`# ${title}\n\n${text}`).slice(0,2000000),content_raw:String(raw.outerHTML||"").slice(0,2000000),source:location.hostname||"browser",type:"page",captured_at:new Date().toISOString()}; }
  let busy=false,autoTimer=null;
  function status(kind,text,detail=""){const dot=$("#cf-status-dot");if(dot)dot.dataset.kind=kind;const t=$("#cf-status");if(t)t.textContent=text;const d=$("#cf-detail");if(d)d.textContent=detail;}
  async function health(){try{const h=await request("/health"),q=h.ai_queue,line=q?`running ${q.running}/${q.concurrency} · queued ${q.queued} · retry ${q.retry_wait}`:"queue unavailable";const el=$("#cf-health");if(el)el.textContent=`hub ok · ai ${h.ai_configured?"on":"off"} · ${line}`;}catch(e){const el=$("#cf-health");if(el)el.textContent=`hub offline · ${e.message||e}`;}}
  async function capture(origin="manual"){if(busy||!/^https?:/i.test(location.href))return;busy=true;status("run",origin==="auto"?"auto snapshot…":"snapshot…",location.href);try{const cfg=await settings();const receipt=await request("/captures",{method:"POST",body:JSON.stringify({...snapshot(),auto_ai:cfg.autoAi,recipe_id:cfg.recipe})});const q=await request("/ai/queue").catch(()=>null);const detail=[`document: ${receipt.document_id}`,`revision: ${receipt.revision_id}`,`deduped: ${receipt.deduped}`,receipt.ai_job?`AI: ${receipt.ai_job.status} · ${receipt.ai_job.id}`:null,receipt.ai_error?`AI enqueue error: ${receipt.ai_error}`:null,q?`queue: running ${q.running}/${q.concurrency} · queued ${q.queued}`:null].filter(Boolean).join("\n");status("ok",receipt.ai_job?`stored · AI ${receipt.ai_job.status}`:receipt.deduped?"deduped":"stored",detail);void health();}catch(e){status("err","failed",e.message||String(e));}finally{busy=false;}}
  async function scheduleAuto(){clearTimeout(autoTimer);const cfg=await settings();if(!cfg.autoCapture||!/^https?:/i.test(location.href))return;autoTimer=setTimeout(()=>void capture("auto"),1200);}
  GM_addStyle(`#cf-root{position:fixed;right:16px;bottom:16px;z-index:2147483646;font:13px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif;color:#e8edf5}#cf-fab{border:0;border-radius:999px;padding:10px 14px;background:#111827;color:#fff;box-shadow:0 8px 30px #0005;cursor:pointer}#cf-panel{display:none;width:min(420px,calc(100vw - 28px));margin-bottom:8px;border:1px solid #334155;border-radius:14px;background:#0f172a;box-shadow:0 18px 50px #0008;overflow:hidden}#cf-root[data-open="1"] #cf-panel{display:block}#cf-root[data-open="1"] #cf-fab{display:none}.cf-head{display:flex;justify-content:space-between;gap:8px;padding:12px 14px;border-bottom:1px solid #263244}.cf-head strong{font-size:15px}.cf-head small{display:block;color:#94a3b8;max-width:290px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cf-body{padding:12px}.cf-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:8px 0}.cf-row label{display:flex;gap:6px;align-items:center}.cf-btn,.cf-input,.cf-select{border:1px solid #334155;border-radius:8px;background:#172033;color:#e8edf5;padding:8px}.cf-btn{cursor:pointer}.cf-primary{background:#2563eb;border-color:#3b82f6}.cf-grow{flex:1;min-width:160px}.cf-log{white-space:pre-wrap;max-height:180px;overflow:auto;border-radius:8px;background:#0b1220;padding:9px;color:#cbd5e1}.cf-muted{color:#94a3b8;font-size:12px}.cf-status{display:flex;gap:8px;align-items:center}.cf-dot{width:8px;height:8px;border-radius:50%;background:#64748b}.cf-dot[data-kind="run"]{background:#f59e0b}.cf-dot[data-kind="ok"]{background:#22c55e}.cf-dot[data-kind="err"]{background:#ef4444}`);
  const root=document.createElement("div");root.id="cf-root";root.innerHTML=`<section id="cf-panel"><div class="cf-head"><div><strong>Capture Flow</strong><small id="cf-hub-label"></small></div><button class="cf-btn" id="cf-close">−</button></div><div class="cf-body"><div class="cf-muted" id="cf-url"></div><div class="cf-row"><label><input id="cf-auto-capture" type="checkbox">新页面自动采集</label><label><input id="cf-auto-ai" type="checkbox">自动加入 AI 队列</label></div><div class="cf-row"><select class="cf-select" id="cf-recipe"><option value="summarize">summarize</option><option value="outline">outline</option><option value="qa-prep">qa-prep</option></select><button class="cf-btn cf-primary" id="cf-capture">立即采集 Snapshot</button></div><div class="cf-row"><input class="cf-input cf-grow" id="cf-hub" type="url"><button class="cf-btn" id="cf-save">保存 Hub</button></div><div class="cf-status"><span class="cf-dot" id="cf-status-dot"></span><strong id="cf-status">idle</strong></div><pre class="cf-log" id="cf-detail">Browser DOM → /captures → durable AI queue</pre><div class="cf-muted" id="cf-health">checking hub…</div></div></section><button id="cf-fab">Capture Flow</button>`;document.documentElement.appendChild(root);
  async function render(){const cfg=await settings();root.dataset.open=cfg.open?"1":"0";$("#cf-hub-label").textContent=cfg.hub;$("#cf-hub").value=cfg.hub;$("#cf-auto-ai").checked=cfg.autoAi;$("#cf-auto-capture").checked=cfg.autoCapture;$("#cf-recipe").value=cfg.recipe;$("#cf-url").textContent=location.href;}
  $("#cf-fab").onclick=async()=>{await set(K.open,true);await render();};$("#cf-close").onclick=async()=>{await set(K.open,false);await render();};$("#cf-capture").onclick=()=>void capture("manual");$("#cf-auto-ai").onchange=e=>set(K.autoAi,e.target.checked);$("#cf-auto-capture").onchange=async e=>{await set(K.autoCapture,e.target.checked);await scheduleAuto();};$("#cf-recipe").onchange=e=>set(K.recipe,e.target.value);$("#cf-save").onclick=async()=>{await set(K.hub,$("#cf-hub").value.trim()||DEFAULT_HUB);await render();await health();};
  document.addEventListener("keydown",e=>{if(e.altKey&&e.shiftKey&&e.code==="KeyC"){e.preventDefault();void capture("manual");}if(e.altKey&&e.shiftKey&&e.code==="KeyP"){e.preventDefault();void get(K.open,true).then(v=>set(K.open,!v)).then(render);}},true);
  let lastHref=location.href;const nav=()=>{if(location.href===lastHref)return;lastHref=location.href;const u=$("#cf-url");if(u)u.textContent=lastHref;void scheduleAuto();};for(const name of ["pushState","replaceState"]){const orig=history[name];history[name]=function(...args){const r=orig.apply(this,args);queueMicrotask(nav);return r;};}addEventListener("popstate",nav);addEventListener("hashchange",nav);setInterval(nav,1000);void render().then(()=>{void health();void scheduleAuto();});
})();
